with q as (insert into public.questions(subject_id,topic_id,statement,options,difficulty,status,fingerprint) select s.id,t.id,'Uma fita de DNA tem sequência 5′-ATGC-3′. Qual é a fita complementar corretamente orientada?','["5′-TACG-3′","3′-TACG-5′","3′-ATGC-5′","5′-UACG-3′"]'::jsonb,9,'published',md5(lower(trim('Uma fita de DNA tem sequência 5′-ATGC-3′. Qual é a fita complementar corretamente orientada?'))) from public.subjects s join public.topics t on t.subject_id=s.id where s.slug='biologia' and t.name='Vida e sistemas' on conflict(fingerprint) do update set updated_at=public.questions.updated_at returning id) insert into private.question_answers(question_id,answer,explanation) select id,1,'As fitas são antiparalelas e as bases se pareiam A–T e G–C. Assim, a complementar é 3′-TACG-5′.' from q on conflict(question_id) do nothing;
